1|// Track selection and manifest parsing. Pure: no env, no fetch, no audio.
2|import { EMOTIONS } from "./types";
3|import type { EmotionId, Vector8 } from "./types";
4|import { buildFeatures } from "./cluster";
5|
6|// Hand label for the track: the single emotion it was made to carry.
7|export type TrackSource = "generated" | "jamendo" | "recording";
8|
9|export interface Playlist {
10|  id: string;
11|  label: string;
12|  trackIds: string[];
13|}
14|
15|// Fixed id for the owner-requested Chopin playlist. The player button
16|// uses the playlist with this id and shows its label verbatim.
17|export const CHOPIN_PLAYLIST_ID = "just-play-chopin";
18|
19|export interface Track {
20|  id: string;
21|  src: string;
22|  title: string;
23|  playlistOnly?: boolean;
24|  emotion: EmotionId;
25|  vector: Vector8;
26|  intensity: number;
27|  tempo: number;
28|  durationSec: number;
29|  startSec: number;
30|  loop: boolean;
31|  soundtrack: string;
32|  style: string;
33|  source?: TrackSource;
34|  artist?: string;
35|  composer?: string;
36|  license?: string;
37|  attribution?: string;
38|  sourceUrl?: string;
39|}
40|
41|export interface StyleInfo {
42|  id: string;
43|  name: string;
44|}
45|
46|export interface Soundtrack {
47|  id: string;
48|  name: string;
49|  style: string;
50|  credit?: string;
51|}
52|
53|export interface MusicManifest {
54|  version: number;
55|  styles: StyleInfo[];
56|  soundtracks: Soundtrack[];
57|  tracks: Track[];
58|  playlists: Playlist[];
59|}
60|
61|// Session selection: style scopes every pick, soundtrackId is the home
62|// in soundtrack mode, mode picks the ranking rule.
63|export interface MusicSelection {
64|  mode: "soundtrack" | "random";
65|  soundtrackId: string | null;
66|  style: string | null;
67|}
68|
69|export type Rng = () => number;
70|
71|export interface SelectEnv {
72|  selection: MusicSelection;
73|  rng: Rng;
74|}
75|
76|export interface PersistedMusicPrefs {
77|  mode: "soundtrack" | "random";
78|  soundtrackId: string | null;
79|  style: string | null;
80|}
81|
82|export interface SceneSignal {
83|  vector: Vector8;
84|  intensity: number;
85|  tempo: number;
86|}
87|
88|export type Similarity = (scene: SceneSignal, track: Track, weights: MusicWeights) => number;
89|
90|export interface MusicWeights {
91|  emotion: number;
92|  intensity: number;
93|  tempo: number;
94|}
95|
96|export interface MusicConfig {
97|  similarity: Similarity;
98|  weights: MusicWeights;
99|  switchMargin: number;
100|  dwellSec: number;
101|  minTrackSec: number;
102|  hardCutMargin: number;
103|  crossfadeSec: number;
104|  hardCutCrossfadeSec: number;
105|  randomTolerance: number;
106|}
107|
108|// Renormalize the 8 entries to sum 1. Extra keys (such as a Jev
109|// "unknown" entry) are ignored. An all-zero vector stays all zero.
110|export function normalize8(vector: Record<string, number>): number[] {
111|  const values = EMOTIONS.map((id: EmotionId) => {
112|    const v = vector[id];
113|    return typeof v === "number" && Number.isFinite(v) ? v : 0;
114|  });
115|  const sum = values.reduce((a, b) => a + b, 0);
116|  if (sum <= 0) return values.map(() => 0);
117|  return values.map((v) => v / sum);
118|}
119|
120|// Bhattacharyya affinity over the renormalized shapes, plus separate
121|// intensity and tempo terms. Fair to blended scenes, unlike cosine.
122|export function bhattacharyyaSimilarity(
123|  scene: SceneSignal,
124|  track: Track,
125|  weights: MusicWeights = MUSIC_CONFIG.weights,
126|): number {
127|  const s = normalize8(scene.vector);
128|  const t = normalize8(track.vector);
129|  let affinity = 0;
130|  for (let i = 0; i < s.length; i++) {
131|    affinity += Math.sqrt((s[i] ?? 0) * (t[i] ?? 0));
132|  }
133|  return (
134|    weights.emotion * affinity +
135|    weights.intensity * (1 - Math.abs(scene.intensity - track.intensity)) +
136|    weights.tempo * (1 - Math.abs(scene.tempo - track.tempo))
137|  );
138|}
139|
140|// Cosine over buildFeatures output (vector plus weighted intensity and
141|// tempo). Kept as an alternative; it favors peaky scenes.
142|export function cosineSimilarity(scene: SceneSignal, track: Track): number {
143|  const a = buildFeatures(scene);
144|  const b = buildFeatures(track);
145|  let dot = 0;
146|  let na = 0;
147|  let nb = 0;
148|  for (let i = 0; i < a.length; i++) {
149|    const x = a[i] ?? 0;
150|    const y = b[i] ?? 0;
151|    dot += x * y;
152|    na += x * x;
153|    nb += y * y;
154|  }
155|  if (na === 0 || nb === 0) return 0;
156|  return dot / (Math.sqrt(na) * Math.sqrt(nb));
157|}
158|
159|export const MUSIC_CONFIG: MusicConfig = {
160|  similarity: bhattacharyyaSimilarity,
161|  weights: { emotion: 0.7, intensity: 0.15, tempo: 0.15 },
162|  switchMargin: 0.07,
163|  dwellSec: 20,
164|  minTrackSec: 45,
165|  hardCutMargin: 0.2,
166|  crossfadeSec: 3,
167|  hardCutCrossfadeSec: 1.5,
168|  // Admits near ties into the random-mode draw without letting clearly
169|  // worse matches in.
170|  randomTolerance: 0.05,
171|};
172|
173|export function resolveConfig(override?: Partial<MusicConfig>): MusicConfig {
174|  if (!override) return MUSIC_CONFIG;
175|  return {
176|    ...MUSIC_CONFIG,
177|    ...override,
178|    weights: override.weights ?? MUSIC_CONFIG.weights,
179|  };
180|}
181|
182|export function scoreTrack(
183|  scene: SceneSignal,
184|  track: Track,
185|  override?: Partial<MusicConfig>,
186|): number {
187|  const config = resolveConfig(override);
188|  return config.similarity(scene, track, config.weights);
189|}
190|
191|// Best score first. Ties go to the lower track id, so ranking is stable.
192|export function rankTracks(
193|  scene: SceneSignal,
194|  manifest: MusicManifest,
195|  override?: Partial<MusicConfig>,
196|): Track[] {
197|  const config = resolveConfig(override);
198|  return [...manifest.tracks].sort((a, b) => {
199|    const diff =
200|      config.similarity(scene, b, config.weights) - config.similarity(scene, a, config.weights);
201|    if (diff !== 0) return diff;
202|    return a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
203|  });
204|}
205|
206|// Dominant emotion of a scene: argmax of the renormalized vector, with
207|// ties broken by EMOTIONS order.
208|export function dominantEmotion(scene: SceneSignal): EmotionId {
209|  const norm = normalize8(scene.vector);
210|  let best: EmotionId = EMOTIONS[0] as EmotionId;
211|  let bestValue = -Infinity;
212|  EMOTIONS.forEach((id: EmotionId, i: number) => {
213|    const value = norm[i] ?? 0;
214|    if (value > bestValue) {
215|      bestValue = value;
216|      best = id;
217|    }
218|  });
219|  return best;
220|}
221|
222|// Reader skip rule: cycle tracks hand-labeled with the scene's dominant
223|// emotion, in score order, wrapping and skipping the current track. When
224|// the current track has another emotion, start at the top candidate. With
225|// no other same-emotion track, fall back to the best track overall that
226|// Style scope for every pick. A null style means the whole manifest,
227|// which only happens before the reader resolves the session style.
228|// Style scope for every pick, minus playlist-only tracks. Playlist tracks
229|// never enter emotion selection, so the filter lives here, not in callers.
230|export function candidatesFor(selection: MusicSelection, manifest: MusicManifest): Track[] {
231|  const audible = manifest.tracks.filter((t) => t.playlistOnly !== true);
232|  if (selection.style === null) return audible;
233|  return audible.filter((t) => t.style === selection.style);
234|}
235|
236|// Home set in soundtrack mode: the session soundtrack, or the whole
237|// style set when none is set yet.
238|export function homeTracks(selection: MusicSelection, styleTracks: Track[]): Track[] {
239|  if (selection.soundtrackId === null) return styleTracks;
240|  const home = styleTracks.filter((t) => t.soundtrack === selection.soundtrackId);
241|  return home.length > 0 ? home : styleTracks;
242|}
243|
244|// "Cambiar track": the next same-emotion track in score order, wrapping
245|// and skipping the current. In soundtrack mode it stays inside the
246|// current track's soundtrack first, then tries the same emotion in other
247|// same-style soundtracks, then the best same-style track overall. In
248|// random mode it ranges over all same-style soundtracks at once. A null
249|// scene cycles the style set in id order. One track or none gives null.
250|export function nextTrack(
251|  scene: SceneSignal | null,
252|  manifest: MusicManifest,
253|  currentTrackId: string | null,
254|  override?: Partial<MusicConfig>,
255|  selection?: MusicSelection | null,
256|): Track | null {
257|  const scope =
258|    selection == null
259|      ? manifest.tracks.filter((t) => t.playlistOnly !== true)
260|      : candidatesFor(selection, manifest);
261|  if (scope.length <= 1) return null;
262|  const config = resolveConfig(override);
263|  const scoped = { ...manifest, tracks: scope };
264|  if (scene === null) {
265|    const ids = [...scope].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
266|    const at = ids.findIndex((t) => t.id === currentTrackId);
267|    return ids[(at + 1) % ids.length] as Track;
268|  }
269|  const ranked = rankTracks(scene, scoped, config);
270|  const same = ranked.filter((t) => t.emotion === dominantEmotion(scene));
271|  const others = same.filter((t) => t.id !== currentTrackId);
272|  if (others.length > 0) {
273|    if (selection?.mode === "random") {
274|      const at = same.findIndex((t) => t.id === currentTrackId);
275|      if (at >= 0) return same[(at + 1) % same.length] as Track;
276|      return same[0] as Track;
277|    }
278|    const current = scope.find((t) => t.id === currentTrackId) ?? null;
279|    const home = current ? same.filter((t) => t.soundtrack === current.soundtrack) : [];
280|    const homeOthers = home.filter((t) => t.id !== currentTrackId);
281|    if (homeOthers.length > 0) {
282|      const at = home.findIndex((t) => t.id === currentTrackId);
283|      if (at >= 0) return home[(at + 1) % home.length] as Track;
284|      return home[0] as Track;
285|    }
286|    const at = same.findIndex((t) => t.id === currentTrackId);
287|    if (at >= 0) return same[(at + 1) % same.length] as Track;
288|    return same[0] as Track;
289|  }
290|  return ranked.find((t) => t.id !== currentTrackId) ?? null;
291|}
292|
293|// Random mode draw: same-style tracks with the scene's dominant emotion
294|// (or the whole style set when none matches), scored, kept within
295|// randomTolerance of the best. The current track stays when eligible;
296|// otherwise the draw skips it when an alternative exists.
297|export function pickRandomTrack(
298|  cands: Track[],
299|  scene: SceneSignal | null,
300|  excludeId: string | null,
301|  rng: Rng,
302|  override?: Partial<MusicConfig>,
303|): Track | null {
304|  if (cands.length === 0) return null;
305|  if (scene === null) {
306|    const ids = [...cands].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
307|    const at = ids.findIndex((t) => t.id === excludeId);
308|    return ids[(at + 1) % ids.length] as Track;
309|  }
310|  const config = resolveConfig(override);
311|  const scoped = { version: 3, styles: [], soundtracks: [], playlists: [], tracks: cands };
312|  const ranked = rankTracks(scene, scoped, config);
313|  const dom = dominantEmotion(scene);
314|  const pool = ranked.filter((t) => t.emotion === dom);
315|  const kept = (pool.length > 0 ? pool : ranked).map((t) => ({
316|    track: t,
317|    score: config.similarity(scene, t, config.weights),
318|  }));
319|  const best = kept[0]?.score ?? 0;
320|  const eligible = kept.filter((e) => e.score >= best - config.randomTolerance);
321|  const current = excludeId !== null ? eligible.find((e) => e.track.id === excludeId) : undefined;
322|  if (current) return current.track;
323|  const rest = eligible.filter((e) => e.track.id !== excludeId);
324|  const drawFrom = rest.length > 0 ? rest : eligible;
325|  if (drawFrom.length === 0) return null;
326|  return (drawFrom[Math.floor(rng() * drawFrom.length)] as { track: Track }).track;
327|}
328|
329|// Distinct hand-labeled emotions on a soundtrack, ignoring playlist-only
330|// tracks. The initial session soundtrack is the one covering most
331|// emotions, ties by lower id.
332|export function soundtrackCoverage(manifest: MusicManifest, soundtrackId: string): number {
333|  return new Set(
334|    manifest.tracks
335|      .filter((t) => t.soundtrack === soundtrackId && t.playlistOnly !== true)
336|      .map((t) => t.emotion),
337|  ).size;
338|}
339|
340|export function pickInitialSoundtrack(
341|  manifest: MusicManifest,
342|  persistedId: string | null,
343|): string | null {
344|  if (persistedId !== null && manifest.soundtracks.some((s) => s.id === persistedId)) {
345|    return persistedId;
346|  }
347|  let best: string | null = null;
348|  let bestCover = -1;
349|  for (const s of manifest.soundtracks) {
350|    if (!manifest.tracks.some((t) => t.soundtrack === s.id && t.playlistOnly !== true)) continue;
351|    const cover = soundtrackCoverage(manifest, s.id);
352|    if (cover > bestCover || (cover === bestCover && (best === null || s.id < best))) {
353|      best = s.id;
354|      bestCover = cover;
355|    }
356|  }
357|  return best;
358|}
359|
360|// True when the style has at least one emotion-selectable track. The style
361|// selector uses this, so a style with only playlist tracks stays hidden.
362|export function styleHasTracks(manifest: MusicManifest, style: string): boolean {
363|  return manifest.tracks.some((t) => t.style === style && t.playlistOnly !== true);
364|}
365|
366|// Session defaults on load. A stored style with no tracks and a stored
367|// soundtrack outside the stored style both fall back to the defaults.
368|export function resolveInitialSelection(
369|  manifest: MusicManifest,
370|  persisted: PersistedMusicPrefs | null,
371|): MusicSelection {
372|  const fallbackId = pickInitialSoundtrack(manifest, null);
373|  const fallbackStyle =
374|    fallbackId !== null
375|      ? (manifest.soundtracks.find((s) => s.id === fallbackId)?.style ?? null)
376|      : null;
377|  const style =
378|    persisted?.style !== null &&
379|    persisted?.style !== undefined &&
380|    styleHasTracks(manifest, persisted.style)
381|      ? persisted.style
382|      : fallbackStyle;
383|  let soundtrackId: string | null = null;
384|  if (style !== null) {
385|    const inStyle = (id: string) =>
386|      manifest.soundtracks.some((s) => s.id === id && s.style === style);
387|    if (
388|      persisted?.soundtrackId !== null &&
389|      persisted?.soundtrackId !== undefined &&
390|      inStyle(persisted.soundtrackId)
391|    ) {
392|      soundtrackId = persisted.soundtrackId;
393|    } else {
394|      let best: string | null = null;
395|      let bestCover = -1;
396|      for (const s of manifest.soundtracks.filter((s) => s.style === style)) {
397|        if (!manifest.tracks.some((t) => t.soundtrack === s.id && t.playlistOnly !== true)) {
398|          continue;
399|        }
400|        const cover = soundtrackCoverage(manifest, s.id);
401|        if (cover > bestCover || (cover === bestCover && (best === null || s.id < best))) {
402|          best = s.id;
403|          bestCover = cover;
404|        }
405|      }
406|      soundtrackId = best;
407|    }
408|  }
409|  return {
410|    mode: persisted?.mode === "random" ? "random" : "soundtrack",
411|    soundtrackId,
