52|  const schedRef = useRef<SchedulerState>(initScheduler());
53|  const liveRef = useRef({ activeId, manifest, selection, currentId, byId, playlistOn });
54|  liveRef.current = { activeId, manifest, selection, currentId, byId, playlistOn };
55|
56|  const nowSec = () => Date.now() / 1000;
57|
58|  const applyDecision = useCallback((decision: {
59|    state: SchedulerState;
60|    switchToId: string | null;
61|    crossfadeSec: number;
62|    fallback: boolean;
63|  }) => {
64|    schedRef.current = decision.state;
65|    setActiveId(decision.state.activeSceneId);
66|    setIsFallback(decision.fallback);
67|    if (decision.switchToId !== null) {
68|      setCurrentId(decision.switchToId);
69|      setFadeSec(decision.crossfadeSec);
70|    }
71|  }, []);
