73|  const persist = useCallback((next: MusicSelection) => {
74|    setSelection(next);
75|    saveMusicPrefs({
76|      mode: next.mode,
77|      soundtrackId: next.soundtrackId,
78|      style: next.style,
79|    });
80|  }, []);
