82|  const observe = useCallback(
83|    (sceneId: string) => {
84|      const st = liveRef.current;
85|      if (!st.manifest || !st.selection) return;
86|      const signal = st.byId.get(sceneId)?.emotion ?? null;
87|      applyDecision(
88|        observeScene(schedRef.current, sceneId, signal, st.manifest, nowSec(), {
89|          selection: st.selection,
90|          rng: Math.random,
91|        }),
92|      );
93|    },
94|    [applyDecision],
95|  );
