165|    const signal = st.byId.get(st.activeId)?.emotion ?? null;
166|    applyDecision(
167|      requestNext(schedRef.current, signal, st.manifest, nowSec(), {
168|        selection: st.selection,
169|        rng: Math.random,
170|      }),
171|    );
172|  }
173|
174|  function togglePlaylist() {
175|    const st = liveRef.current;
176|    if (!st.manifest || !st.selection) return;
177|    const playlist = findChopinPlaylist(st.manifest);
178|    if (!playlist) return;
179|    if (st.playlistOn) {
180|      const signal = (st.activeId && st.byId.get(st.activeId)?.emotion) || null;
181|      applyDecision(
182|        exitPlaylist(schedRef.current, signal ?? null, st.manifest, nowSec(), {
183|          selection: st.selection,
184|          rng: Math.random,
185|        }),
186|      );
