361|  if (!playlist || playlist.trackIds.length === 0) return noChange(state);
362|  const nextIndex = (state.playlist.index + 1) % playlist.trackIds.length;
363|  const nextId = playlist.trackIds[nextIndex];
364|  if (nextId === undefined || nextId === state.currentId) return noChange(state);
365|  const next = manifest.tracks.find((t) => t.id === nextId) ?? null;
366|  if (!next) return noChange(state);
367|  return {
368|    state: {
369|      ...state,
370|      currentId: next.id,
371|      currentStartedSec: nowSec,
372|      overrideId: null,
373|      overrideSceneId: null,
374|      playlist: { id: playlist.id, index: nextIndex },
375|    },
376|    switchToId: next.id,
377|    crossfadeSec: state.currentId === null ? 0 : config.crossfadeSec,
